import { useEffect, useState } from 'react'
import {
  getRoleList,
  getRolePermissionsList,
  getRolePermissionsDetail,
  addRole,
  PermissionTypes
} from '@/apis/admin/permission'
import { Card, Button, message, Checkbox, Space, Tag, Empty, Modal, Form, Input, Alert } from 'antd'
import {
  SaveOutlined,
  PlusOutlined,
  UserOutlined,
  DownOutlined,
  RightOutlined,
  InfoCircleOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'

// 权限模块配置（与原型图对应）
const PERM_MODULE_ICONS: Record<string, string> = {
  device: '📱',
  product: '📦',
  order: '📋',
  user: '👥',
  ad: '📢',
  permission: '🔐',
  statistics: '📊',
  setting: '⚙️'
}

const RoleManagement: React.FC = () => {
  const [roleList, setRoleList] = useState<PermissionTypes.AdminRoleListDto[]>([])
  const [currentRole, setCurrentRole] = useState<PermissionTypes.AdminRoleListDto | null>(null)
  const [permissionsList, setPermissionsList] = useState<
    PermissionTypes.AdminRolePermissionsListDto[]
  >([])
  const [rolePermissions, setRolePermissions] = useState<
    PermissionTypes.AdminRolePermissionsDetailDto[]
  >([])
  const [selectedPerms, setSelectedPerms] = useState<Set<string>>(new Set())
  const [expandedModules, setExpandedModules] = useState<Set<number>>(new Set())
  const [loading, setLoading] = useState(false)
  const [saveLoading, setSaveLoading] = useState(false)
  const [modalVisible, setModalVisible] = useState(false)
  const [form] = Form.useForm()

  // 初始化加载角色列表和权限列表
  useEffect(() => {
    fetchInitialData()
  }, [])

  // 当前角色变化时加载角色权限
  useEffect(() => {
    if (currentRole) {
      fetchRolePermissions(currentRole.id)
    }
  }, [currentRole])

  const fetchInitialData = async () => {
    setLoading(true)
    try {
      const [roleRes, permRes] = await Promise.all([getRoleList(), getRolePermissionsList()])

      if (roleRes.code === ResultEnum.SUCCESS) {
        const roles = roleRes.data?.list || []
        setRoleList(roles)
        if (roles.length > 0 && !currentRole) {
          setCurrentRole(roles[0])
        }
      }

      if (permRes.code === ResultEnum.SUCCESS) {
        const perms = permRes.data?.List || []
        setPermissionsList(perms)
        // 默认展开所有模块
        setExpandedModules(new Set(perms.map(p => p.id)))
      }
    } catch (e) {
      message.error('加载数据失败')
    } finally {
      setLoading(false)
    }
  }

  const fetchRolePermissions = async (roleId: number) => {
    try {
      const res = await getRolePermissionsDetail(roleId)
      if (res.code === ResultEnum.SUCCESS) {
        const perms = res.data?.List || []
        setRolePermissions(perms)
        // 设置选中的权限
        const selected = new Set(perms.map(p => p.permKey).filter(Boolean))
        setSelectedPerms(selected)
      }
    } catch (e) {
      console.error('获取角色权限失败', e)
      setSelectedPerms(new Set())
    }
  }

  // 切换模块展开/收起
  const toggleModule = (moduleId: number) => {
    setExpandedModules(prev => {
      const next = new Set(prev)
      if (next.has(moduleId)) {
        next.delete(moduleId)
      } else {
        next.add(moduleId)
      }
      return next
    })
  }

  // 选择/取消选择权限
  const handlePermChange = (permKey: string, checked: boolean) => {
    setSelectedPerms(prev => {
      const next = new Set(prev)
      if (checked) {
        next.add(permKey)
      } else {
        next.delete(permKey)
      }
      return next
    })
  }

  // 检查权限是否被选中
  const isPermChecked = (permKey: string) => {
    return selectedPerms.has(permKey)
  }

  // 保存权限配置
  const handleSavePermissions = async () => {
    if (!currentRole) {
      return
    }

    setSaveLoading(true)
    try {
      // TODO: 等待后端提供保存权限配置的接口
      // 目前接口只有添加角色，没有更新角色权限的接口
      message.success('权限配置已保存')
    } catch (e) {
      message.error('保存失败')
    } finally {
      setSaveLoading(false)
    }
  }

  // 打开新增角色弹窗
  const openAddModal = () => {
    form.resetFields()
    setModalVisible(true)
  }

  // 提交新增角色
  const handleAddRole = async () => {
    try {
      const values = await form.validateFields()
      const res = await addRole({
        roleName: values.roleName,
        remark: values.remark || ''
      })

      if (res.code === ResultEnum.SUCCESS) {
        message.success('新增角色成功')
        setModalVisible(false)
        fetchInitialData()
      } else {
        message.error(res.message || '操作失败')
      }
    } catch (e) {
      console.error(e)
    }
  }

  // 判断是否为超级管理员
  const isSuperAdmin = (roleName: string) => {
    return roleName?.includes('超级') || roleName?.includes('super')
  }

  return (
    <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: 20 }}>
      {/* 左侧角色列表 */}
      <Card
        title="角色列表"
        loading={loading}
        extra={
          <Button type="primary" icon={<PlusOutlined />} size="small" onClick={openAddModal}>
            新增角色
          </Button>
        }
      >
        <Space direction="vertical" style={{ width: '100%' }}>
          {roleList.map(role => (
            <div
              key={role.id}
              onClick={() => setCurrentRole(role)}
              style={{
                padding: 16,
                borderRadius: 8,
                cursor: 'pointer',
                border: '2px solid',
                borderColor: currentRole?.id === role.id ? '#1890ff' : '#f0f0f0',
                backgroundColor: currentRole?.id === role.id ? '#e6f7ff' : '#fff',
                transition: 'all 0.2s ease',
                marginBottom: 12
              }}
            >
              <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 4 }}>{role.roleName}</div>
              <div style={{ fontSize: 12, color: '#64748B', marginBottom: 8 }}>
                {isSuperAdmin(role.roleName) ? '拥有所有权限' : '自定义权限配置'}
              </div>
              <div style={{ fontSize: 12, color: '#999' }}>
                <UserOutlined style={{ marginRight: 4 }} />
                {role.userNum || 0} 人
              </div>
            </div>
          ))}
        </Space>

        <Alert
          message="加盟商和运维人员不登录PC后台，通过XLINK小程序管理端管理"
          type="warning"
          showIcon
          icon={<InfoCircleOutlined />}
          style={{ marginTop: 16 }}
        />
      </Card>

      {/* 右侧权限配置 */}
      <Card
        title="权限配置"
        loading={loading}
        extra={
          currentRole &&
          !isSuperAdmin(currentRole.roleName) && (
            <Button
              type="primary"
              icon={<SaveOutlined />}
              loading={saveLoading}
              onClick={handleSavePermissions}
            >
              保存
            </Button>
          )
        }
      >
        {currentRole ? (
          <>
            <div style={{ marginBottom: 20 }}>
              <div style={{ fontSize: 16, fontWeight: 600, marginBottom: 4 }}>
                {currentRole.roleName}
                {isSuperAdmin(currentRole.roleName) && (
                  <Tag color="red" style={{ marginLeft: 8 }}>
                    超级管理员
                  </Tag>
                )}
              </div>
              <div style={{ fontSize: 13, color: '#64748B' }}>
                {isSuperAdmin(currentRole.roleName)
                  ? '超级管理员拥有所有权限，无需配置'
                  : '请勾选该角色拥有的权限项'}
              </div>
            </div>

            {isSuperAdmin(currentRole.roleName) ? (
              <Empty
                description="超级管理员自动拥有所有权限"
                image={Empty.PRESENTED_IMAGE_SIMPLE}
              />
            ) : (
              <Space direction="vertical" style={{ width: '100%' }}>
                {permissionsList.map(module => {
                  const isExpanded = expandedModules.has(module.id)
                  return (
                    <div
                      key={module.id}
                      style={{
                        marginBottom: 16,
                        border: '1px solid #f0f0f0',
                        borderRadius: 8,
                        overflow: 'hidden'
                      }}
                    >
                      {/* 模块头部 */}
                      <div
                        onClick={() => toggleModule(module.id)}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: 10,
                          padding: '12px 16px',
                          background: '#F8FAFC',
                          fontSize: 14,
                          fontWeight: 600,
                          cursor: 'pointer',
                          userSelect: 'none'
                        }}
                      >
                        {isExpanded ? <DownOutlined /> : <RightOutlined />}
                        <span style={{ fontSize: 16 }}>
                          {PERM_MODULE_ICONS[module.name] || '📁'}
                        </span>
                        <span>{module.name}</span>
                      </div>

                      {/* 模块内容 */}
                      {isExpanded && (
                        <div style={{ padding: '12px 16px' }}>
                          {module.child?.map(child => (
                            <div
                              key={child.id}
                              style={{
                                marginBottom: 12,
                                padding: 10,
                                background: '#F8FAFC',
                                borderRadius: 6
                              }}
                            >
                              <div
                                style={{
                                  fontSize: 13,
                                  fontWeight: 600,
                                  color: '#334155',
                                  marginBottom: 8
                                }}
                              >
                                {child.name}
                              </div>
                              <div
                                style={{
                                  display: 'flex',
                                  flexWrap: 'wrap',
                                  gap: '8px 24px'
                                }}
                              >
                                {child.permKey?.split(',').map((perm: string) => {
                                  const permName = perm.trim()
                                  if (!permName) {
                                    return null
                                  }
                                  return (
                                    <Checkbox
                                      key={`${child.id}-${permName}`}
                                      checked={isPermChecked(`${child.permKey}:${permName}`)}
                                      onChange={e =>
                                        handlePermChange(
                                          `${child.permKey}:${permName}`,
                                          e.target.checked
                                        )
                                      }
                                    >
                                      {permName}
                                    </Checkbox>
                                  )
                                })}
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  )
                })}
              </Space>
            )}
          </>
        ) : (
          <Empty description="请选择角色" />
        )}
      </Card>

      {/* 新增角色弹窗 */}
      <Modal
        title="新增角色"
        open={modalVisible}
        onOk={handleAddRole}
        onCancel={() => setModalVisible(false)}
        width={480}
      >
        <Form form={form} layout="vertical" style={{ marginTop: 16 }}>
          <Form.Item
            label="角色名称"
            name="roleName"
            rules={[{ required: true, message: '请输入角色名称' }]}
          >
            <Input placeholder="请输入角色名称，如：运营专员" />
          </Form.Item>
          <Form.Item label="备注" name="remark">
            <Input.TextArea rows={3} placeholder="请输入角色描述，如：负责日常运营和设备维护" />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  )
}

export default RoleManagement
